import Foundation
import GymCore

/// Creative Commons photos from wger.de, looked up in the bundled mapping (`wger-photos.json`, generated by
/// `scripts/map-wger.mjs`; review: docs/import/wger-review.md). Each photo carries the credit its license requires
/// (shown on the exercise detail photo). Loaded on demand from wger's media server and cached like any other photo.
/// Last in the chain: it only fills gaps left by own and free-exercise-db photos.
struct WgerPhotoProvider: ExerciseMediaProvider {
    static let resourceName = "wger-photos"
    static let host = "wger.de"

    private struct Mapping: Decodable {
        let photos: [String: [Entry]]
    }

    private struct Entry: Decodable {
        let url: String
        let title: String
        let author: String
        let license: String
        let licenseUrl: String?
        let sourceUrl: String?
        let modified: Bool?
    }

    private let media: [String: ExerciseMedia]

    init(data: Data) throws {
        let mapping = try JSONDecoder().decode(Mapping.self, from: data)
        media = mapping.photos.compactMapValues { entries in
            let valid = entries.compactMap(Self.photo)
            // All or nothing per exercise, like the free-exercise-db mapping: never a half-credited pair.
            guard !valid.isEmpty, valid.count == entries.count else { return nil }
            return ExerciseMedia(photos: valid.map(\.url), animation: nil, source: .wger, credits: valid.map(\.credit))
        }
    }

    /// The bundled mapping, or nil when the resource is missing or unreadable (those exercises keep illustrations).
    static func bundled(_ bundle: Bundle = .main) -> WgerPhotoProvider? {
        guard let url = bundle.url(forResource: resourceName, withExtension: "json"),
              let data = try? Data(contentsOf: url) else { return nil }
        do { return try WgerPhotoProvider(data: data) } catch {
            MediaLog.log.error("wger photo mapping unreadable: \(error.localizedDescription, privacy: .public)")
            return nil
        }
    }

    func media(for exercise: Exercise) -> ExerciseMedia? { media[exercise.id] }

    /// An https wger.de media URL with a non-blank author and license; anything else is dropped.
    private static func photo(_ entry: Entry) -> (url: URL, credit: PhotoCredit)? {
        guard let url = URL(string: entry.url), url.scheme == "https", url.host()?.lowercased() == host,
              url.path().hasPrefix("/media/") else { return nil }
        let author = entry.author.trimmingCharacters(in: .whitespacesAndNewlines)
        let license = entry.license.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !author.isEmpty, !license.isEmpty else { return nil }
        let credit = PhotoCredit(title: entry.title, author: author, license: license,
                                 licenseURL: entry.licenseUrl.flatMap(URL.init(string:)),
                                 sourceURL: entry.sourceUrl.flatMap(URL.init(string:)), modified: entry.modified ?? true)
        return (url, credit)
    }
}
